// Splits the single file openapi-typescript writes into files of at most `maxLines` lines (the
// repository allows no source file over 500 lines, generated ones included). The input is the
// oxfmt-formatted output: top-level `export interface X {` … `}` blocks with members indented by
// two spaces, plus one-line `export type X = …;` aliases.

const HEADER = [
  '/**',
  ' * Generated by `pnpm --filter @agent-team/client generate` (openapi-typescript) from',
  ' * packages/protocol/openapi.json. Do not edit by hand.',
  ' */',
  '',
];

interface Block {
  name: string;
  lines: string[];
}

function topLevelBlocks(source: string): Block[] {
  const lines = source.split('\n');
  const blocks: Block[] = [];
  let current: Block | undefined;
  for (const line of lines) {
    if (current) {
      current.lines.push(line);
      if (line === '}') {
        blocks.push(current);
        current = undefined;
      }
      continue;
    }
    const iface = /^export interface (\w+) \{$/.exec(line);
    if (iface) {
      current = { name: iface[1]!, lines: [line] };
      continue;
    }
    const alias = /^export type (\$?\w+) = .*;$/.exec(line);
    if (alias) blocks.push({ name: alias[1]!, lines: [line] });
  }
  if (current) throw new Error(`unterminated block ${current.name}`);
  return blocks;
}

/** Members of an interface block (each starts at two-space indentation). */
function members(block: Block): string[][] {
  const body = block.lines.slice(1, -1);
  const out: string[][] = [];
  let pending: string[] = [];
  for (const line of body) {
    pending.push(line);
    // a member ends with a two-space-indented line closing it (`  };`) or a one-line member
    if (/^ {2}\S/.test(line) && (line.endsWith(';') || line === '  };')) {
      out.push(pending);
      pending = [];
    }
  }
  if (pending.length > 0) out.push(pending);
  return out;
}

function referencedTypes(text: string, self: string): string[] {
  return ['paths', 'components', 'operations'].filter(
    (name) => name !== self && new RegExp(`\\b${name}\\[`).test(text),
  );
}

function fileOf(name: string): string {
  return name === 'webhooks' ? 'paths' : name === '$defs' ? 'components' : name;
}

function render(imports: string[], body: string[]): string {
  const head = imports.length > 0 ? [...imports, ''] : [];
  return [...HEADER, ...head, ...body, ''].join('\n');
}

/** File name (`paths.ts`, …) → content, plus `index.ts` re-exporting every type. */
export function splitGenerated(source: string, maxLines = 450): Map<string, string> {
  const files = new Map<string, string[]>();
  const exported: Array<[string, string]> = [];
  for (const block of topLevelBlocks(source)) {
    const file = fileOf(block.name);
    exported.push([block.name, file]);
    const body = files.get(file) ?? [];
    if (block.lines.length + body.length + HEADER.length + 4 <= maxLines) {
      body.push(...block.lines);
      files.set(file, body);
      continue;
    }
    // too long: split the interface into numbered parts joined by an intersection type
    const parts: string[][] = [];
    let part: string[] = [];
    for (const member of members(block)) {
      if (part.length > 0 && part.length + member.length + HEADER.length + 6 > maxLines) {
        parts.push(part);
        part = [];
      }
      part.push(...member);
    }
    if (part.length > 0) parts.push(part);
    const partNames = parts.map((_, i) => `${block.name}_part${i + 1}`);
    parts.forEach((lines, i) => {
      files.set(`${block.name}-part-${i + 1}`, [
        `export interface ${partNames[i]} {`,
        ...lines,
        '}',
      ]);
    });
    body.push(`export type ${block.name} = ${partNames.join(' & ')};`);
    files.set(file, body);
  }

  const out = new Map<string, string>();
  for (const [file, body] of files) {
    const text = body.join('\n');
    const own = file.replace(/-part-\d+$/, '');
    const imports = referencedTypes(text, own).map(
      (name) => `import type { ${name} } from './${name}.js';`,
    );
    const parts = new Set(
      [...text.matchAll(/\b(\w+)_part(\d+)\b/g)]
        .filter(([, base]) => base === file)
        .map(([, base, n]) => `import type { ${base}_part${n} } from './${base}-part-${n}.js';`),
    );
    out.set(`${file}.ts`, render([...imports, ...parts], body));
  }
  const index = exported.map(([name, file]) => `export type { ${name} } from './${file}.js';`);
  out.set('index.ts', render([], index));
  return out;
}
